  toFullyProtectYourDevicePlease: { en: 'To fully protect your device, please enable the accessibility service. This prevents unauthorized app removal.', et: 'Seadme turvalisuse tagamiseks lubage juurdepääsetavuse teenus. See kaitseb rakendust eemaldamise eest.', no: 'For å fullstendig beskytte enheten din, vennligst aktiver tilgjengelighetstjenesten. Dette forhindrer uautorisert fjerning av apper.', sv: 'För att helt skydda din enhet, aktivera vänligen tillgänglighetstjänsten. Detta förhindrar obehörig borttagning av appar.', da: 'For fuld beskyttelse af din enhed, aktiver venligst tilgængelighedstjenesten. Dette forhindrer uautoriseret app-fjernelse.', fi: 'Suojataksesi laitteesi täysin, ota käyttöön saavutettavuuspalvelu. Tämä estää luvattoman sovelluksen poistamisen.', lv: 'Lai pilnībā aizsargātu savu ierīci, lūdzu, aktivizējiet pieejamības servisu. Tas novērš neautorizētu lietotņu noņemšanu.', lt: 'Norint visiškai apsaugoti jūsų įrenginį, įjunkite prieinamumo paslaugą. Tai užkerta kelią nepagrįstam programų šalinimui.', de_at: 'Um Ihr Gerät vollständig zu schützen, aktivieren Sie bitte den Barrierefreiheitsdienst. Dies verhindert die unbefugte Entfernung von Apps.', cs: 'Aby bylo vaše zařízení plně chráněno, aktivujte prosím službu přístupnosti. To zabraňuje neoprávněnému odstranění aplikací.', pl: 'Aby w pełni chronić swoje urządzenie, włącz usługę dostępu. Zapobiega to nieautoryzowanemu usunięciu aplikacji.', de_ch: 'Um Ihr Gerät vollständig zu schützen, aktivieren Sie bitte den Barrierefreiheitsdienst. Dies verhindert die unbefugte Entfernung von Apps.', es: 'Para proteger completamente su dispositivo, habilite el servicio de accesibilidad. Esto previene la eliminación no autorizada de aplicaciones.', de: 'Um Ihr Gerät vollständig zu schützen, aktivieren Sie bitte den Barrierefreiheitsdienst. Dies verhindert die unbefugte Entfernung von Apps.', fr: 'Pour protéger pleinement votre appareil, veuillez activer le service d\'accessibilité. Cela empêche la suppression non autorisée des applications.', it: 'Per proteggere completamente il tuo dispositivo, abilita il servizio di accessibilità. Questo previene la rimozione non autorizzata delle app.' },
  toSecureYourDevicePleaseEnable: { en: 'To secure your device, please enable Device Admin permissions.', et: 'Seadme turvaliseks kasutamiseks luba administraatori õigused.', no: 'For å sikre enheten din, vennligst aktiver Device Admin-rettigheter.', sv: 'För att säkra din enhet, aktivera vänligen behörigheter för enhetsadministration.', da: 'For at sikre din enhed, aktiver venligst Device Admin rettigheder.', fi: 'Suojataksesi laitteesi, ota käyttöön Laitehallinnan oikeudet.', lv: 'Lai nodrošinātu jūsu ierīci, lūdzu, aktivizējiet ierīces administratora atļaujas.', lt: 'Norint apsaugoti jūsų įrenginį, įjunkite Įrenginio administratoriaus teises.', de_at: 'Um Ihr Gerät zu sichern, aktivieren Sie bitte die Berechtigungen für den Geräteadministrator.', cs: 'Pro zabezpečení vašeho zařízení povolte prosím oprávnění správce zařízení.', pl: 'Aby zabezpieczyć swoje urządzenie, włącz uprawnienia administratora urządzenia.', de_ch: 'Um Ihr Gerät zu sichern, aktivieren Sie bitte die Berechtigungen für den Geräteadministrator.', es: 'Para asegurar su dispositivo, habilite los permisos de Administrador de Dispositivo.', de: 'Um Ihr Gerät zu sichern, aktivieren Sie bitte die Berechtigungen für den Geräteadministrator.', fr: 'Pour sécuriser votre appareil, veuillez activer les permissions d\'Admin de l\'Appareil.', it: 'Per proteggere il tuo dispositivo, abilita i permessi di Device Admin.' },
